service.method:

SELECT
		  USER_ID
		, MENU_PROFILE_CODE
FROM
	SUSMT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}	
	AND USER_ID 		= ${PERSONID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${DISPLAYNAME}
		, USER_NAME_ENG	 	= ${DISPLAYNAMEENG}
		, DEPT		      	= ${DEPTCODE}
		, POSITION		  	= ${ROLECODE}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${MOBILETEL}
		, DEL_FLAG        	= ${DEL_FLAG}
		, MENU_PROFILE_CODE = ${MENU_PROFILE_CODE}
		, LANGUAGE			= ${LANGUAGE}
WHERE
	  HOUSE_CODE        	= ${session.HOUSE_CODE}
  AND USER_ID           	= ${PERSONID}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, COMPANY_CODE
		, PLANT_CODE
		, USER_NAME_LOC
		, USER_NAME_ENG
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL				
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${PERSONID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${session.COMPANY_CODE}
		, ${session.COMPANY_CODE}
		, ${DISPLAYNAME}
		, ${DISPLAYNAMEENG}
		, ${PASSWORD}
		, ${DEPTCODE}
		, ${ROLECODE}
		, ${EMAIL}				
		, 'KR'
		, 'A'
		, 'Z'
		, ${MENU_PROFILE_CODE}
		, ${USER_TYPE}
		, '0'
		, 'Y'
		, ${DEL_FLAG}
		, '%Y/%m/%d'
		, ${MOBILETEL}
		, ${LANGUAGE}
	)


		UPDATE SADDR
			SET
				  CHANGE_DATE     = ${current.DATE}
				, CHANGE_TIME     = ${current.TIME}
				, CHANGE_USER_ID  = ${session.ID}			  
				, DEL_FLAG        = ${DEL_FLAG}
				, PHONE_NO1       = ${MOBILETEL}
				, EMAIL           = ${EMAIL}
		WHERE
              HOUSE_CODE        = ${session.HOUSE_CODE}
		  AND CODE_NO           = ${PERSONID}


INSERT INTO SADDR
	(
		  HOUSE_CODE
		, CODE_NO 
		, CODE_TYPE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, DEL_FLAG
		, PHONE_NO1
		, EMAIL				
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${PERSONID}
		, 'USER'
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, 'N'
		, ${MOBILETEL}
		, ${EMAIL}				
	)


UPDATE SCODE
	SET
		  TEXT1		      = ${GRADENAME}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}	
		, SORT_SEQ		  = ${SORT_SEQ}		  
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
	AND TYPE 		      = 'UX049'
	AND CODE              = ${GRADECODE}
	AND LANGUAGE 		  = ${LANGUAGE}


INSERT INTO SCODE
	(
		  HOUSE_CODE
		, TYPE 
		, CODE
		, LANGUAGE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, SORT_SEQ
		, USE_FLAG
		, TEXT1
		, DEL_FLAG
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, 'UX049'
		, ${GRADECODE}
		, ${LANGUAGE}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, ${SORT_SEQ}
		, 'Y'
		, ${GRADENAME}
		, 'N'
	)
